/**
 * Server-only identity resolution: establishment_digest → company_ref.
 *
 * The identity projection (identity_projection.json) is a private, sealed
 * document that maps establishment_digest to company_ref. It is:
 * - Generated by extra-cli (producer side)
 * - Mounted via confenge-host-file-record (not served statically)
 * - Never exposed to the client
 * - Only used in server-side handoff to Warmbly
 *
 * Fail-closed: missing or invalid projection returns null, never raises.
 * The handoff still succeeds without company_ref — it's enrichment, not blocker.
 */
const { safeLog } = require("./lead-core.cjs");

const PROJECTION_SCHEMA = "CONFENGE_IDENTITY_PROJECTION/1.0";

let _projectionOverride = null;
function setProjectionForTests(proj) {
  _projectionOverride = proj;
}

function loadProjection(env = process.env) {
  if (_projectionOverride) return _projectionOverride;
  try {
    // eslint-disable-next-line global-require
    return require("../../data/live_intelligence/live/.private/identity_projection.json");
  } catch (err) {
    return null;
  }
}

/**
 * Validate the projection structure. Returns null if invalid.
 */
function validateProjection(proj) {
  if (!proj || typeof proj !== "object") return null;
  if (proj.schema !== PROJECTION_SCHEMA) return null;
  if (!proj.snapshot_id || typeof proj.snapshot_id !== "string") return null;
  if (!proj.sealed_to_manifest_hash || typeof proj.sealed_to_manifest_hash !== "string") return null;
  if (!Array.isArray(proj.entries)) return null;
  if (!proj.sealed_hash || typeof proj.sealed_hash !== "string") return null;
  return proj;
}

/**
 * Build an index map: establishment_digest → company_ref.
 * Returns empty object if projection is unavailable or malformed.
 */
function buildDigestToRefMap(proj) {
  const map = {};
  if (!proj || !Array.isArray(proj.entries)) return map;
  for (const entry of proj.entries) {
    if (entry && entry.establishment_digest && entry.company_ref) {
      map[String(entry.establishment_digest)] = String(entry.company_ref);
    }
  }
  return map;
}

/**
 * Resolve establishment_digest to company_ref.
 *
 * Returns the company_ref string if found, or null if:
 * - digest is falsy or not a string
 * - projection is unavailable
 * - projection is invalid
 * - digest is not in the projection
 *
 * Never throws. Errors are logged, not surfaced.
 */
function resolveCompanyRef(establishmentDigest, opts = {}) {
  const env = opts.env || process.env;
  const proj = opts.projection || loadProjection(env);
  const digest = String(establishmentDigest || "").trim();

  if (!digest) return null;
  if (!proj) return null;

  const validated = validateProjection(proj);
  if (!validated) {
    safeLog("warn", "identity_projection_invalid", {
      reason: "projection_validation_failed",
    });
    return null;
  }

  const map = buildDigestToRefMap(validated);
  const ref = map[digest] || null;

  if (!ref && process.env.NODE_ENV === "test") {
    // In tests, log lookup misses for inspection
    safeLog("debug", "identity_projection_lookup_miss", {
      digest: digest.slice(0, 8),
    });
  }

  return ref;
}

module.exports = {
  PROJECTION_SCHEMA,
  loadProjection,
  validateProjection,
  buildDigestToRefMap,
  resolveCompanyRef,
  setProjectionForTests,
};
